INSERT INTO toeic_questions (id, part, section, prompt, choices, answer, explanation, grammar_tag, topic) VALUES
(660, 5, 'reading', 'The quarterly sales meeting has been moved ___ Room 305.', '["to", "for", "with", "by"]', 0, 'Chuyen dia diem sang phong moi: moved to Room 305. EN: A change of location uses "moved to".', 'prepositions', 'meetings'),
(661, 5, 'reading', 'All new hires must complete safety training ___ starting work.', '["before", "after", "until", "while"]', 0, 'Dao tao truoc khi bat dau lam: before starting work. EN: The training comes first, so "before" fits.', 'prepositions', 'hr'),
(662, 5, 'reading', 'The restaurant is famous ___ its fresh seafood dishes.', '["as", "for", "with", "to"]', 1, '"Be famous for + dac diem" (noi tieng ve...). EN: "Famous for + a feature" is the fixed collocation.', 'prepositions', 'travel'),
(663, 5, 'reading', 'Please remember to turn off the projector ___ leaving the room.', '["after", "before", "until", "during"]', 1, 'Tat may truoc khi roi phong: before leaving. EN: Switching off comes first, so "before" fits.', 'prepositions', 'office'),
(664, 5, 'reading', 'The package ___ yesterday afternoon, so it should arrive soon.', '["shipped", "was shipped", "ships", "has shipped"]', 1, 'Bi dong qua khu (goi hang duoc gui): was shipped. EN: Passive past for the parcel: was shipped.', 'passive', 'logistics'),
(665, 5, 'reading', 'Our team leader is ___ responsible for client communication.', '["direct", "directly", "direction", "directed"]', 1, 'Trang tu bo nghia cum "is responsible": directly. EN: An adverb must modify the adjective phrase: directly.', 'word-forms', 'office'),
(666, 5, 'reading', 'The seminar will focus ___ digital marketing trends.', '["in", "on", "at", "with"]', 1, '"Focus on + chu de" (tap trung vao...). EN: "Focus" pairs with "on".', 'prepositions', 'marketing'),
(667, 5, 'reading', 'Tickets for the trade fair can be purchased ___ at the entrance.', '["either online or", "neither online or", "both online and", "not only online but"]', 0, 'Lua chon 1 trong 2: either... or... EN: A choice between two options uses "either... or".', 'conjunctions', 'sales'),
(668, 5, 'reading', 'She was promoted to regional manager ___ her excellent performance.', '["in spite of", "instead of", "because of", "regardless of"]', 2, 'Nguyen nhan tich cuc (thanh tich xuat sac): because of. EN: A positive cause takes "because of".', 'conjunctions', 'hr'),
(669, 5, 'reading', 'The construction project is expected to be finished ___ December.', '["before", "by", "until", "since"]', 1, 'Hoan thanh cham nhat vao thang 12: by December. EN: A completion deadline uses "by".', 'prepositions', 'manufacturing'),
(670, 5, 'reading', 'Customers ___ pay by credit card receive a 5 percent discount.', '["who", "which", "whose", "whom"]', 0, 'Menh de quan he chi nguoi lam chu ngu: who. EN: People as subject of the clause need "who".', 'relative-clauses', 'sales'),
(671, 5, 'reading', 'The new employee handbook ___ all company policies in detail.', '["outlines", "outline", "outlined", "outlining"]', 0, 'Chu ngu so it (handbook) + hien tai don: outlines. EN: A singular subject in present simple takes "outlines".', 'agreement', 'hr'),
(672, 5, 'reading', 'We apologize for the delay and appreciate your ___.', '["patient", "patience", "patiently", "patients"]', 1, 'Can danh tu sau "your": patience (su kien nhan). EN: After "your", use the noun: patience.', 'word-forms', 'support'),
(673, 5, 'reading', 'The conference room on the third floor can ___ up to fifty people.', '["accommodate", "accommodation", "accommodating", "accommodated"]', 0, 'Sau "can" dung dong tu nguyen mau: accommodate. EN: After "can", use the base verb: accommodate.', 'tenses', 'meetings'),
(674, 5, 'reading', 'Flight delays are common ___ the rainy season.', '["during", "while", "until", "since"]', 0, 'Trong suot mua mua: during the rainy season. EN: Throughout a season takes "during".', 'prepositions', 'travel'),
(675, 5, 'reading', 'He has attended every training session ___ joining the company.', '["since", "for", "during", "from"]', 0, '"Since + moc thoi gian" (joining = luc gia nhap). EN: "Since + a starting point" marks the beginning.', 'prepositions', 'hr'),
(676, 5, 'reading', 'The report must be reviewed ___ by two managers before submission.', '["thorough", "thoroughly", "thoroughness", "through"]', 1, 'Trang tu bo nghia dong tu "be reviewed": thoroughly. EN: An adverb must modify "be reviewed": thoroughly.', 'word-forms', 'office'),
(677, 5, 'reading', '___ the increase in fuel prices, bus fares will rise next month.', '["Due to", "Despite", "Unless", "Although"]', 0, 'Nguyen nhan (gia nhien lieu tang): Due to. EN: A stated cause takes "Due to".', 'conjunctions', 'logistics'),
(678, 5, 'reading', 'The library will be open ___ 8 a.m. to 10 p.m. on weekdays.', '["between", "from", "among", "with"]', 1, 'Khung gio "from 8 a.m. to 10 p.m.". EN: A time range opens with "from".', 'prepositions', 'general'),
(679, 5, 'reading', 'Not only the manager but also the staff ___ satisfied with the new schedule.', '["is", "are", "was", "be"]', 1, 'Dong tu chia theo chu ngu gan nhat (staff, so nhieu): are. EN: "Not only... but also" agrees with the nearer subject: staff -> are.', 'agreement', 'hr'),
(680, 5, 'reading', 'The company plans to expand ___ Southeast Asian markets next year.', '["into", "onto", "upon", "over"]', 0, 'Mo rong sang thi truong moi: expand into. EN: Market entry uses "expand into".', 'prepositions', 'sales'),
(681, 5, 'reading', 'All receipts must be kept for at ___ five years for tax purposes.', '["least", "last", "late", "less"]', 0, 'Cum co dinh "at least" (it nhat). EN: "At least" is the fixed phrase meaning no fewer than.', 'vocabulary', 'finance'),
(682, 5, 'reading', 'The keynote speaker discussed ways to improve customer ___.', '["satisfy", "satisfaction", "satisfied", "satisfying"]', 1, 'Can danh tu sau "customer": satisfaction (su hai long). EN: After "customer", use the noun: satisfaction.', 'word-forms', 'marketing'),
(683, 5, 'reading', 'You can reach the support hotline ___ dialing 1800-5555.', '["by", "with", "in", "through"]', 0, 'Chi phuong thuc lien lac: by dialing. EN: The method of contact uses "by + V-ing".', 'prepositions', 'support'),
(684, 5, 'reading', 'The merger will create one of the ___ logistics firms in Asia.', '["larger", "large", "largest", "largely"]', 2, 'So sanh nhat voi "one of the": largest. EN: "One of the" needs the superlative.', 'comparatives', 'logistics'),
(685, 5, 'reading', 'Employees are encouraged to take regular breaks ___ stay productive.', '["in order", "so as", "to", "for to"]', 2, 'Chi muc dich ngan gon: to + V (to stay). EN: A short purpose clause uses "to + verb".', 'conjunctions', 'hr'),
(686, 5, 'reading', 'The quality control team checks every batch ___ it leaves the factory.', '["before", "after", "until", "during"]', 0, 'Kiem tra truoc khi xuat xuong: before it leaves. EN: Inspection comes first, so "before" fits.', 'prepositions', 'manufacturing'),
(687, 5, 'reading', 'Her presentation on market trends was both informative ___ engaging.', '["but", "or", "and", "nor"]', 2, 'Cap song song "both... and...". EN: "Both" pairs with "and".', 'conjunctions', 'marketing'),
(688, 5, 'reading', 'The office will remain closed ___ Monday morning due to repairs.', '["until", "by", "since", "during"]', 0, 'Dong cua keo dai den sang thu 2: until Monday morning. EN: A continuing state up to a point uses "until".', 'prepositions', 'office'),
(689, 5, 'reading', 'Mr. Lee recommended ___ the budget proposal before the vote.', '["reviewing", "to review", "review", "reviewed"]', 0, '"Recommend + V-ing" (de nghi lam...). EN: "Recommend" is followed by a gerund.', 'gerunds', 'finance'),
(690, 5, 'reading', 'The new regulations apply to all businesses ___ in the downtown area.', '["operating", "operate", "operates", "to operate"]', 0, 'Rut gon menh de quan he: businesses operating (= which operate). EN: A reduced relative clause uses the present participle: operating.', 'tenses', 'general'),
(691, 5, 'reading', 'A shuttle bus runs ___ the hotel and the convention center hourly.', '["between", "among", "across", "along"]', 0, 'Noi 2 diem cu the: between the hotel and... EN: Two named points take "between".', 'prepositions', 'travel'),
(692, 5, 'reading', 'The intern was praised for completing tasks quickly and ___.', '["accurate", "accuracy", "accurately", "accurateness"]', 2, 'Song song voi trang tu "quickly": accurately. EN: Parallel with the adverb "quickly" needs "accurately".', 'word-forms', 'hr'),
(693, 5, 'reading', 'Sales figures for March exceeded our expectations ___ a large margin.', '["by", "with", "in", "for"]', 0, 'Vuot ky vong mot khoang lon: by a large margin. EN: A margin of difference uses "by".', 'prepositions', 'sales'),
(694, 5, 'reading', 'The museum offers guided tours ___ English and Japanese daily.', '["on", "in", "at", "by"]', 1, 'Tour bang ngon ngu nao: in English and Japanese. EN: A language used takes "in".', 'prepositions', 'travel'),
(695, 5, 'reading', 'Had the supplier delivered on time, we ___ avoided the penalty.', '["would have", "will have", "have", "had"]', 0, 'Cau dieu kien loai 3 (dao ngu): would have + V3. EN: Inverted third conditional needs "would have + past participle".', 'conditionals', 'logistics'),
(696, 5, 'reading', 'The annual charity auction raised ___ $200,000 for local schools.', '["over", "above", "beyond", "across"]', 0, 'Vuot moc 200.000 do la: over $200,000. EN: Exceeding an amount uses "over".', 'prepositions', 'finance'),
(697, 5, 'reading', 'All meeting rooms ___ be booked in advance through the portal.', '["must", "have", "ought", "need"]', 0, 'Bat buoc dat truoc: must be booked. EN: Obligation uses "must".', 'tenses', 'meetings'),
(698, 5, 'reading', 'The graphic designer created a ___ logo for the rebranding campaign.', '["striking", "strike", "struck", "strikingly"]', 0, 'Tinh tu bo nghia "logo": striking (an tuong). EN: An adjective must modify "logo": striking.', 'word-forms', 'marketing'),
(699, 5, 'reading', 'Please direct all media inquiries ___ our communications office.', '["to", "for", "with", "at"]', 0, 'Chuyen cau hoi bao chi den bo phan: direct... to... EN: Directing something somewhere uses "to".', 'prepositions', 'office'),
(700, 5, 'reading', 'The software automatically saves your work every five ___.', '["minute", "minutes", "minutely", "minuted"]', 1, 'Sau "five" can danh tu so nhieu: minutes. EN: After "five", use the plural noun: minutes.', 'agreement', 'it'),
(701, 5, 'reading', 'Wages will be paid ___ on the 5th of each month.', '["direct", "directly", "direction", "directed"]', 1, 'Trang tu bo nghia "be paid": directly. EN: An adverb must modify "be paid": directly.', 'word-forms', 'finance'),
(702, 5, 'reading', 'The product launch attracted media coverage from around the ___.', '["world", "word", "work", "worth"]', 0, 'Bao chi khap the gioi: around the world. EN: Global coverage uses "around the world".', 'vocabulary', 'marketing'),
(703, 5, 'reading', 'Travelers are advised to arrive at the station 30 minutes ___ departure.', '["ahead of", "instead of", "except for", "apart from"]', 0, 'Den som hon gio khoi hanh: ahead of departure. EN: Earlier than an event uses "ahead of".', 'prepositions', 'travel'),
(704, 5, 'reading', 'The committee members ___ the proposal after a long debate.', '["approval", "approving", "approved", "approves"]', 2, 'Qua khu don voi chu ngu so nhieu: approved (phe chuan). EN: Simple past with a plural subject: approved.', 'tenses', 'meetings'),
(705, 5, 'reading', 'Customers with overdue accounts will receive a reminder ___ mail.', '["by", "with", "in", "through"]', 0, 'Gui qua duong buu dien: by mail. EN: Postal delivery uses "by mail".', 'prepositions', 'finance'),
(706, 5, 'reading', 'The new mall features over fifty stores, ___ a large food court.', '["include", "includes", "including", "included"]', 2, 'Bao gom (lie ke them): including. EN: Adding examples uses "including".', 'tenses', 'sales'),
(707, 5, 'reading', 'Employees should avoid ___ personal phones during meetings.', '["to use", "use", "using", "used"]', 2, '"Avoid + V-ing" (tranh lam...). EN: "Avoid" is followed by a gerund.', 'gerunds', 'office'),
(708, 5, 'reading', 'The repair will take ___ three hours to complete.', '["approximately", "approximate", "approximation", "approximated"]', 0, 'Trang tu bo nghia cum so luong: approximately. EN: An adverb must modify the quantity phrase: approximately.', 'word-forms', 'support'),
(709, 5, 'reading', '___ Ms. Park is the project lead, all updates go through her.', '["Since", "Despite", "Unless", "Without"]', 0, '"Since" o day nghia la "vi" (ly do). EN: "Since" here means "because".', 'conjunctions', 'office'),
(710, 5, 'reading', 'The invoice ___ a 2 percent discount for payments within ten days.', '["offers", "offer", "offering", "offered"]', 0, 'Chu ngu so it (invoice) + hien tai don: offers. EN: A singular subject takes "offers".', 'agreement', 'finance'),
(711, 5, 'reading', 'The resort provides complimentary breakfast ___ all guests.', '["for", "to", "with", "at"]', 0, 'Mien phi danh cho khach: for all guests. EN: The beneficiary takes "for".', 'prepositions', 'travel'),
(712, 5, 'reading', 'Production costs have risen sharply, forcing the company to raise ___.', '["prize", "prices", "pricy", "pricing"]', 1, 'Can danh tu so nhieu sau "raise": prices. EN: After "raise", use the plural noun "prices".', 'word-forms', 'manufacturing'),
(713, 5, 'reading', 'The seminar room is equipped ___ modern audiovisual devices.', '["with", "by", "in", "for"]', 0, 'Trang bi kem thiet bi: equipped with. EN: "Equipped" pairs with "with".', 'prepositions', 'meetings'),
(714, 5, 'reading', 'Had we known about the traffic jam, we ___ taken a different route.', '["would have", "will have", "have", "had"]', 0, 'Cau dieu kien loai 3: would have + V3. EN: Third conditional needs "would have + past participle".', 'conditionals', 'travel'),
(715, 5, 'reading', 'All visitors must sign in at reception ___ receiving a guest badge.', '["before", "after", "until", "during"]', 0, 'Ky ten truoc khi nhan the: before receiving. EN: Signing comes first, so "before" fits.', 'prepositions', 'office'),
(716, 5, 'reading', 'The marketing team launched the campaign two weeks ahead of ___.', '["schedule", "scheduled", "scheduling", "schedules"]', 0, 'Cum co dinh "ahead of schedule" (som hon ke hoach). EN: "Ahead of schedule" is the fixed phrase for early completion.', 'vocabulary', 'marketing'),
(717, 5, 'reading', 'Only senior engineers are authorized to approve design ___.', '["change", "changes", "changing", "changed"]', 1, 'Phe duyet cac thay doi (dem duoc): changes. EN: Countable modifications need the plural "changes".', 'word-forms', 'manufacturing'),
(718, 5, 'reading', 'The client requested that the draft contract ___ revised by Monday.', '["be", "is", "was", "has been"]', 0, 'Thuc gia dinh sau "request that": be + V3. EN: Subjunctive after "request that" uses the base form: be revised.', 'subjunctive', 'contracts'),
(719, 5, 'reading', 'Profits this quarter were slightly ___ than analysts predicted.', '["low", "lower", "lowest", "lowly"]', 1, 'So sanh hon voi "than": lower. EN: A comparison with "than" needs the comparative: lower.', 'comparatives', 'finance')
